  constructor(
    private readonly maintenance: MaintenanceService,
    private readonly mileage: MileageService,
  ) {}

  async openOrder(input: OpenOrderInput): Promise<Record<string, string | number>> {
    if (input.estimatedHours <= 0 || input.estimatedHours > 40) {
      throw new FleetError('Estimates must be between 0 and 40 hours', 400);
